function comparisonControls(basis=false){const opts=[['budget',state.year+' budget'],...availableYears().filter(y=>y!==+state.year).map(y=>[y,y+' actual'])];if(!opts.some(([v])=>String(v)===reviewComparison))reviewComparison='budget';return `<div class="toolbar">${select('reviewComparison','Compare with',opts,reviewComparison)}${basis?select('reviewBasis','Show costs as',[['amount','Actual amount (total)'],['per','Cost per metric tonne']],state.basis):''}</div>`;}
